# Independent old-value spot check from pypdf text extraction for every reported modification.
import json,re
from pypdf import PdfReader
r=json.load(open('/root/diff_report.json'))
want={x['id']:x for x in r['modified_employees']}
reader=PdfReader('/root/employees_backup.pdf')
found={}
for page in reader.pages:
 for line in (page.extract_text() or '').splitlines():
  m=re.match(r'(EMP\d{5})\s',line)
  if m and m.group(1) in want: found[m.group(1)]=line
assert set(found)==set(want),(set(want)-set(found))
for eid in sorted(found): print(found[eid])
